mapper.select:
SELECT id, artifact_id, file_version_no, archive_batch_id, business_decision_ref,
       archived_by, archived_at, archive_note, created_at, tenant_id
FROM plt_file_archive_record
WHERE tenant_id = #{query.tenantId}
  AND archive_batch_id = #{query.archiveBatchId}
  AND artifact_id = #{query.artifactId}
  AND file_version_no = #{query.versionNo}
